arguments.content:
qasm_string = """
OPENQASM 3.0;
include "stdgates.inc";
gate oracle q0, q1, q2, q3, q4, q5 {
    // Set q[4] and q[5] to |10⟩ (representing base-3 value 2)
    x q[5];
    // Determine x₁ (second trit) from q[1], q[2]
    // x₁ = 0: |00⟩, x₁ = 1: |01⟩, x₁ = 2: |10⟩
    // Helper: set q[3] = 1 when x₁ = 2
    x q[1];
    x q[2];
    ccx q[1], q[2], q[3];
    x q[1];
    x q[2];
    // Compute f(x)₁ = (x₀ + 2) mod 3
    // CNOT: q[0] controls q[4]
    cx q[0], q[4];
    // Compute f(x)₀
    // When x₁ = 0 or 1: f(x)₀ = x₀
    // When x₁ = 2: f(x)₀ = (x₀ + 1) mod 3
    // CNOT: q[3] controls q[4]
    cx q[3], q[4];
    // Toffoli: when x₀ = 1 and x₁ = 2, set q[5] = |1⟩
    ccx q[0], q[3], q[5];
}
qubit[6] q;
oracle q[0], q[1], q[2], q[3], q[4], q[5];
"""

